/* Modal legal con focus trap y Escape */
function LegalModal({ type, onClose }) {
  const content = LEGAL_CONTENT[type];
  const modalRef = useRef(null);
  const closeRef = useRef(null);

  useEffect(() => {
    closeRef.current?.focus();
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const handleKey = (e) => {
      if (e.key === "Escape") { onClose(); return; }
      if (e.key !== "Tab") return;
      const focusable = modalRef.current?.querySelectorAll('button,[href],input,[tabindex]:not([tabindex="-1"])');
      if (!focusable || focusable.length === 0) return;
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (e.shiftKey) { if (document.activeElement === first) { e.preventDefault(); last.focus(); } }
      else { if (document.activeElement === last) { e.preventDefault(); first.focus(); } }
    };
    document.addEventListener("keydown", handleKey);
    return () => { document.removeEventListener("keydown", handleKey); document.body.style.overflow = prev; };
  }, [onClose]);

  if (!content) return null;
  return (
    <div
      role="dialog" aria-modal="true" aria-labelledby="legal-modal-title"
      onClick={e => e.target === e.currentTarget && onClose()}
      style={{ position: "fixed", inset: 0, zIndex: 1100, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "flex-end", justifyContent: "center" }}
    >
      <div ref={modalRef} style={{ background: "#fff", width: "100%", maxWidth: 600, borderRadius: "20px 20px 0 0", maxHeight: "85vh", display: "flex", flexDirection: "column", animation: "fadeUp .3s ease" }}>
        {/* Header fijo */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "20px 24px", borderBottom: "1px solid #E5E7EB", flexShrink: 0 }}>
          <h2 id="legal-modal-title" className="fm" style={{ fontWeight: 800, fontSize: 18, color: "#1D1D1F" }}>{content.title}</h2>
          <button ref={closeRef} onClick={onClose} aria-label={`Cerrar ${content.title}`} style={{ background: "none", border: "none", cursor: "pointer", color: "#6B7280", padding: 4, borderRadius: 8 }}>
            <X size={22} />
          </button>
        </div>
        {/* Contenido scrollable */}
        <div style={{ overflowY: "auto", padding: "24px", flex: 1 }}>
          {content.body.map(({ h, p }) => (
            <div key={h} style={{ marginBottom: 24 }}>
              <h3 className="fm" style={{ fontSize: 14, fontWeight: 700, color: "#1D1D1F", marginBottom: 8 }}>{h}</h3>
              <p style={{ fontSize: 14, color: "#4B5563", lineHeight: 1.75 }}>{p}</p>
            </div>
          ))}
          <div style={{ background: "#F9FAFB", borderRadius: 12, padding: "14px 16px", marginTop: 8 }}>
            <p style={{ fontSize: 12, color: "#9CA3AF", lineHeight: 1.6 }}>
              Este texto tiene carácter informativo. Para garantizar el cumplimiento legal específico de tu actividad, te recomendamos asesoramiento jurídico profesional. Última actualización: enero 2025.
            </p>
          </div>
        </div>
        {/* Footer fijo */}
        <div style={{ padding: "16px 24px", borderTop: "1px solid #E5E7EB", flexShrink: 0 }}>
          <button onClick={onClose} style={{ width: "100%", background: "#1D1D1F", color: "#fff", border: "none", borderRadius: 10, padding: "13px", fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: "Montserrat, sans-serif" }}>
            Cerrar
          </button>
        </div>
      </div>
    </div>
  );
}

